    width: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutputMode {
    Rich,   // Full rich formatting
    Plain,  // Text without ANSI codes
    Json,   // JSON output only
    Quiet,  // Minimal output
