## Technical Requirements

### Color Scheme
```rust
use colored::Colorize;

// Status colors
fn status_color(status: &Status) -> ColoredString {
    match status {
        Status::Open => "open".green(),
        Status::InProgress => "in_progress".yellow(),
        Status::Closed => "closed".bright_black(),
    }
}

// Priority colors
fn priority_color(priority: u8) -> ColoredString {
    match priority {
        0 => "P0".red().bold(),        // Critical - red bold
        1 => "P1".red(),               // High - red
        2 => "P2".yellow(),            // Medium - yellow
        3 => "P3".bright_black(),      // Low - gray
        4 => "P4".bright_black(),      // Backlog - gray
        _ => format!("P{}", priority).normal(),
    }
}

// Issue type colors
fn type_color(issue_type: &IssueType) -> ColoredString {
    match issue_type {
        IssueType::Bug => "bug".red(),
        IssueType::Feature => "feature".cyan(),
        IssueType::Task => "task".normal(),
        IssueType::Epic => "epic".magenta().bold(),
        IssueType::Docs => "docs".blue(),
        IssueType::Chore => "chore".bright_black(),
    }
}
